	has_game_rule = harsh_ai_behavior
	scope:target_country = { is_player = yes }
}

# root = country
# scope:target_state = state
# scope:target_country = state owner
ai_state_ambition_claim = {
	scope:target_state = { has_claim_by = root }
}

ai_state_ambition_homeland = {
	scope:target_state = { is_homeland_of_country_cultures = root }
}

ai_state_ambition_capital_region = {
	scope:target_state.region ?= capital.region # Always desire states in home region
	can_reach_target_state_to_conquer = { TARGET_STATE = scope:target_state }
}

ai_state_ambition_split_state = { # The AI wants to unify split states
	scope:target_state = {
		is_split_state = yes
		state_region = {
			any_scope_state = {
				owner = root
				is_treaty_port = no
			}
		}
	}
}

ai_state_ambition_border = {
	scope:target_state = {
		any_neighbouring_state = {
			owner = {
				OR = {
					this = root
					is_subject_of = root
				}
			}
		}
	}
}

ai_state_ambition_colonial = {
	scope:target_country = { ai_country_is_valid_colonization_target = yes }
	can_reach_target_state_to_conquer = { TARGET_STATE = scope:target_state }
}

ai_state_ambition_overlord_gift = { # The AI wants nearby states if gifted them by its overlord
	has_strategic_adjacency = scope:target_state
	any_overlord_or_above = { this = scope:target_country }
}

ai_state_ambition_sphere = {
	scope:target_state.region ?= {
		root = {
			OR = {
				has_strategic_region_interest_tier = {
					strategic_region = prev
					value >= interest_tier_effect_can_start_diplomatic_plays_min_tier
				}
				has_region_stance = {
					region = prev
					stance = stance_conquer_region
				}
				has_region_stance = {
					region = prev
					stance = stance_colonize_region
				}
			}
		}
	}
	can_reach_target_state_to_conquer = { TARGET_STATE = scope:target_state }
}

ai_state_ambition_regional_objective = {
	OR = {
		is_regional_objective_target_state = {
			type = aro:ai_regional_objective_acquire_states
			target = scope:target_state
		}
		is_regional_objective_target_state = {
			type = aro:ai_regional_objective_recover_claims
			target = scope:target_state
		}
	}
	can_reach_target_state_to_conquer = { TARGET_STATE = scope:target_state }
}

# A state the AI treats as a core national interest rather than an opportunity
ai_state_has_core_ambition = {
	OR = {
		ai_state_ambition_claim = yes
		ai_state_ambition_homeland = yes
		ai_state_ambition_capital_region = yes
		ai_state_ambition_split_state = yes
		ai_state_ambition_regional_objective = yes
	}
}

ai_state_is_invalid_target = {
	scope:target_country = { is_still_learning = yes } # Be nice to tutorial players
}

has_enactment_je_or_law_commitment = {
	OR = {
		has_journal_entry = je_government_petition
		has_journal_entry = je_law_imposition
		has_journal_entry = je_british_dictate_law
		has_journal_entry = je_government_petition_negotiation_version
		has_journal_entry = je_government_petition_negotiation_version_b
		has_journal_entry = je_tenpo_crisis
		has_any_law_commitment = yes
		je_tsarpoints_has_law_agenda = yes
		congress_poland_ai_has_law_agenda = yes
	}
}

ai_has_reasons_to_not_oppose_law = {
	OR = {
		has_law_commitment = scope:law.type
		any_political_movement = {
			law_enactment_stance = {
				law = scope:law.type
				value > neutral
			}
			OR = {
				political_movement_radicalism >= 0.75
				AND = {
					political_movement_radicalism >= 0.25
					any_influenced_interest_group = {
						is_in_government = yes
					}
					relevant_law_is_critical_to_modernization = yes
				}
			}
		}
		AND = {
			has_journal_entry = je_government_petition
			var:desired_law_var ?= scope:law
		}
		AND = {
			OR = {
				has_journal_entry = je_government_petition_negotiation_version
				has_journal_entry = je_government_petition_negotiation_version_b
			}
			any_interest_group = {
				has_variable = desired_law_var
				var:desired_law_var	?= scope:law
			}
		}
		AND = {
			OR = {
				has_journal_entry = je_law_imposition
				has_journal_entry = je_british_dictate_law
			}
			imposed_law ?= scope:law.type
		}
		je_tsarpoints_ai_wants_law = yes
		congress_poland_ai_wants_law = yes
	}
}

ai_has_enact_weight_modifier_journal_entries = {
	OR = {
		has_law_commitment = scope:law.type
		AND = {
			has_journal_entry = je_government_petition
			has_variable = desired_law_var
			scope:law = var:desired_law_var
		}
		AND = {
			OR = {
				has_journal_entry = je_law_imposition
				has_journal_entry = je_british_dictate_law
			}
			scope:law = imposed_law
		}
		AND = {
			has_journal_entry = je_gyojo_shinwon
			OR = {
				scope:law = scope:donghak_desired_law_1
				scope:law = scope:donghak_desired_law_2
				scope:law = scope:donghak_desired_law_3
			}
		}
		AND = {
			has_strategy = ai_strategy_confrontation_agenda
			has_journal_entry = je_state_and_revolution
			OR = {
				scope:law.type = law_type:law_communal_administration
				scope:law.type = law_type:law_revolutionary_guard
				scope:law.type = law_type:law_factory_councils
			}
		}
		AND = {
			has_strategy = ai_strategy_consolidation_agenda
			has_journal_entry = je_state_and_revolution
			OR = {
				scope:law.type = law_type:law_mass_conscription
				scope:law.type = law_type:law_appointed_bureaucrats
			}
		}
		AND = {
			has_strategy = ai_strategy_confrontation_agenda
			has_journal_entry = je_social_revolution
			OR = {
				scope:law.type = law_type:law_multicultural
				scope:law.type = law_type:law_womens_suffrage
				scope:law.type = law_type:law_no_colonial_affairs
				scope:law.type = law_type:law_public_schools
				scope:law.type = law_type:law_public_health_insurance
				scope:law.type = law_type:law_old_age_pension
				scope:law.type = law_type:law_worker_protections
			}
		}
		je_tsarpoints_ai_wants_law = yes
		congress_poland_ai_wants_law = yes
	}
}

has_je_conquest_reason = {
	OR = {
		AND = {
			has_journal_entry = je_sick_man_syria
			exists = c:EGY
			$TARGET$ = c:EGY
		}

		AND = {
			has_journal_entry = je_opium_wars
			$TARGET$ = {
				has_variable = opium_wars_target
			}
		}

		AND = {
			has_journal_entry = je_boxer_rebellion
			$TARGET$ = {
				any_scope_state = {
					state_region = { is_homeland = cu:han }
				}
			}
		}

		AND = {
			has_journal_entry = je_greek_nationalism
			$TARGET$ = {
				any_scope_state = {
					state_region = { is_homeland = cu:greek }
					has_claim_by = root
				}
			}
		}

		AND = {
			has_journal_entry = je_consolidate_colonial_rule
			$TARGET$ = {
				is_country_type = unrecognized
				target_is_our_or_fellow_subject = no
				any_scope_state = {
					OR = {
						is_in_geographic_region = geographic_region_india
						is_in_geographic_region = geographic_region_burma
					}
				}
			}
		}

		AND = {
			has_journal_entry = je_tp_pool_develop_frontier
			$TARGET$ = {
				any_scope_state = {
					OR = {
						is_in_geographic_region = geographic_region_siberia
						is_in_geographic_region = geographic_region_central_asia
						is_in_geographic_region = geographic_region_caucasus_old
					}
				}
			}
		}

		AND = {
			has_strategy = ai_strategy_unify_china
			$TARGET$ = {
				has_journal_entry = je_reunify_china
			}
		}

		AND = {
			has_journal_entry = je_age_of_princes
			has_strategy = ai_strategy_unify_ethiopia
			$TARGET$ = {
				any_scope_state = {
					OR = {
						state_region = s:STATE_AMHARA
						state_region = s:STATE_GONDER
					}
				}
			}
		}

		AND = {
			has_journal_entry = je_manifest_destiny_mexico
			$TARGET$ = {
				any_scope_state = {
					OR = {
						state_region = s:STATE_CALIFORNIA
						state_region = s:STATE_NEVADA
						state_region = s:STATE_UTAH
						state_region = s:STATE_COLORADO
						state_region = s:STATE_ARIZONA
						state_region = s:STATE_NEW_MEXICO
						state_region = s:STATE_TEXAS
					}
				}
			}
		}

		AND = {
			has_journal_entry = je_conquer_oregon
			$TARGET$ = {
				any_scope_state = {
					OR = {
						state_region = s:STATE_WASHINGTON
						state_region = s:STATE_IDAHO
						state_region = s:STATE_OREGON
					}
				}
			}
		}

		AND = {
			has_journal_entry = je_alaska
			$TARGET$ = {
				any_scope_state = {
					state_region = s:STATE_ALASKA
				}
			}
		}

		AND = {
			country_has_primary_culture = cu:russian
			has_law_or_variant = law_type:law_national_supremacy
			$TARGET$ = {
				any_scope_state = {
					OR = {
						state_region = s:STATE_KUBAN
						state_region = s:STATE_DAGESTAN
					}
				}
			}
		}

		AND = {
			wants_to_solve_schleswig_holstein = yes
			$TARGET$ = {
				is_oppressor_of_schleswig_holstein = yes
			}
		}

		AND = {
			has_strategy = ai_strategy_unify_germany
			is_unification_candidate = GER
			$TARGET$ = {
				is_unification_candidate = GER
			}
		}

		AND = {
			has_journal_entry = je_conquest_of_algeria
			$TARGET$ = {
				any_scope_state = {
					OR = {
						state_region = s:STATE_ALGIERS
						state_region = s:STATE_CONSTANTINE
						state_region = s:STATE_ORAN
						state_region = s:STATE_SAHARA
						state_region = s:STATE_EAST_SAHARA
					}
				}
			}
		}

		AND = {
			has_journal_entry = je_eastern_frontier
			$TARGET$ = {
				any_scope_state = {
					OR = {
						is_in_geographic_region = geographic_region_persia_old
						is_in_geographic_region = geographic_region_central_asia_old
						is_in_geographic_region = geographic_region_india
					}
					has_claim_by = ROOT
				}
			}
		}

		AND = {
			has_journal_entry = je_conquest_of_central_asia
			$TARGET$ = {
				any_scope_state = {
					OR = {
						state_region = s:STATE_UZBEKIA
						state_region = s:STATE_KIRGHIZIA
						state_region = s:STATE_KHIVA
						state_region = s:STATE_TURKMENIA
						state_region = s:STATE_TAJIKISTAN
					}
				}
			}
			can_reach_target_country_to_conquer = { TARGET_COUNTRY = scope:target_country }
		}

		AND = {
			has_journal_entry = je_unify_afghanistan
			is_afghan_nation = yes
			$TARGET$ = {
				OR = {
					is_afghan_nation = yes
					any_scope_state = {
						OR = {
							state_region = s:STATE_KABUL
							state_region = s:STATE_HERAT
							state_region = s:STATE_KANDAHAR
							state_region = s:STATE_CENTRAL_HIGHLANDS
						}
					}
				}
			}
		}

		AND = {
			c:GBR ?= this
			has_variable = committed_to_afghanistan_assistance
			$TARGET$ = {
				has_variable = AFG_appealed_to_RUS
			}
		}

		AND = {
			c:RUS ?= this
			has_variable = committed_to_afghanistan_assistance
			$TARGET$ = {
				has_variable = AFG_appealed_to_GBR
			}
		}

		AND = {
			c:RUS ?= this
			is_involved_in_journal_entry = je_caucasian_war
			$TARGET$ = {
				OR = {
					c:CIR ?= this
					c:CHC ?= this
				}
			}
		}

		AND = {
